CREATE TABLE customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, email TEXT, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
ALTER TABLE leads ADD COLUMN customer_id INTEGER REFERENCES customers(id);
CREATE INDEX leads_customer_idx ON leads(customer_id);
ALTER TABLE quotations ADD COLUMN customer_id INTEGER REFERENCES customers(id);
CREATE INDEX quotations_customer_idx ON quotations(customer_id);
ALTER TABLE jobs ADD COLUMN customer_id INTEGER REFERENCES customers(id);
CREATE INDEX jobs_customer_idx ON jobs(customer_id);
ALTER TABLE invoices ADD COLUMN customer_id INTEGER REFERENCES customers(id);
CREATE INDEX invoices_customer_idx ON invoices(customer_id);
ALTER TABLE leads ADD COLUMN deleted_at TEXT;
CREATE INDEX leads_deleted_idx ON leads(deleted_at);
INSERT OR IGNORE INTO customers(name,phone,email,created_at,updated_at) SELECT name, CASE WHEN length(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=12 AND substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,2)='91' THEN substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),3) WHEN length(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=11 AND substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,1)='0' THEN substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),2) ELSE replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', '') END, email, created_at, created_at FROM leads WHERE phone IS NOT NULL AND trim(phone)!='' AND move_type!='Contact enquiry' ORDER BY created_at;
UPDATE leads SET customer_id=(SELECT id FROM customers WHERE phone=CASE WHEN length(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=12 AND substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,2)='91' THEN substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),3) WHEN length(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=11 AND substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,1)='0' THEN substr(replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),2) ELSE replace(replace(replace(replace(replace(replace(trim(phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', '') END);
INSERT OR IGNORE INTO customers(name,phone,email,created_at,updated_at) SELECT customer_name, CASE WHEN length(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=12 AND substr(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,2)='91' THEN substr(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),3) WHEN length(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''))=11 AND substr(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),1,1)='0' THEN substr(replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', ''),2) ELSE replace(replace(replace(replace(replace(replace(trim(customer_phone), '+', ''), ' ', ''), '-', ''), '(', ''), ')', ''), '.', '') END, NULL, created_at, created_at FROM quotations WHERE customer_phone IS NOT NULL AND trim(customer_phone)!='' ORDER BY created_at;
